// Service worker: works offline, checks for expiring food in the background (Chrome's periodic
// sync) and shows alerts sent by the optional push server.
import { parseTime } from './js/dates.js';
import { kvGet } from './js/kv.js';
import { claimDue, markNotified, showNotifications } from './js/notify-core.js';

// <precache> generated by scripts/precache.mjs; run `npm run precache` after changing app files
const VERSION = 'f0ef1df77def';
const ASSETS = [
  'css/app.css',
  'icons/apple-touch-icon.png',
  'icons/badge-96.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon.svg',
  'icons/maskable-512.png',
  'index.html',
  'js/alerts.js',
  'js/barcode.js',
  'js/dates.js',
  'js/db.js',
  'js/events.js',
  'js/foods.js',
  'js/ics.js',
  'js/ingredients.js',
  'js/kv.js',
  'js/main.js',
  'js/mealdb-ingredients.js',
  'js/nav.js',
  'js/notify-core.js',
  'js/notify.js',
  'js/platform.js',
  'js/products.js',
  'js/push.js',
  'js/recipe-data.js',
  'js/recipes.js',
  'js/scanner.js',
  'js/settings.js',
  'js/store.js',
  'js/text.js',
  'js/ui.js',
  'js/views/alerts.js',
  'js/views/edit.js',
  'js/views/item.js',
  'js/views/pantry.js',
  'js/views/recipe.js',
  'js/views/recipes.js',
  'js/views/scan.js',
  'js/views/settings.js',
  'js/views/shared.js',
  'manifest.webmanifest',
  'vendor/barcode-detector.js',
  'vendor/zxing_reader.wasm',
];
// </precache>

const CACHE_PREFIX = 'pantry-pal-';
const CACHE = `${CACHE_PREFIX}${VERSION}`;
const scope = () => self.registration.scope;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(ASSETS.map((path) => new Request(new URL(path, scope()), { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Only our own caches: other apps can share this origin (e.g. on github.io).
      const old = (await caches.keys()).filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE);
      await Promise.all(old.map((key) => caches.delete(key)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(scope()) || url.pathname.includes('/api/')) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      // Every screen is index.html plus a #route, so navigations get the cached app shell.
      const key = request.mode === 'navigate' ? new URL('index.html', scope()).href : request;
      const hit = await cache.match(key, { ignoreSearch: true });
      return hit ?? fetch(request);
    })(),
  );
});

/** Don't wake anyone up: background checks stay quiet overnight unless that's when alerts are set. */
async function isQuietHour(now = new Date()) {
  const settings = await kvGet('settings', {});
  const [alertHour] = parseTime(settings.notifyTime);
  const hour = now.getHours();
  return hour >= Math.max(22, alertHour + 1) || hour < Math.min(7, alertHour);
}

async function backgroundCheck() {
  if (await isQuietHour()) return;
  const due = await claimDue(Date.now());
  if (due.notifications.length) await showNotifications(self.registration, due.notifications);
}

self.addEventListener('periodicsync', (event) => {
  if (event.tag === 'expiry-check') event.waitUntil(backgroundCheck());
});

const text = (value, max) => (typeof value === 'string' ? value.slice(0, max) : '');

/** Only plain text and in-app links from the push server. */
function cleanNotification(n) {
  return {
    title: text(n?.title, 120) || 'Pantry Pal',
    body: text(n?.body, 400),
    tag: text(n?.tag, 80) || 'pantry-pal',
    url: typeof n?.url === 'string' && n.url.startsWith('#/') ? n.url : '#/alerts',
  };
}

async function handlePush(event) {
  let data = {};
  try {
    data = event.data?.json() ?? {};
  } catch {
    // not JSON: show the generic alert below
  }
  const keys = Array.isArray(data.keys) ? data.keys.filter((k) => typeof k === 'string') : [];
  let notifications = Array.isArray(data.notifications) ? data.notifications.slice(0, 2).map(cleanNotification) : [];
  if (!notifications.length) {
    notifications = [cleanNotification({ title: '🍳 Pantry Pal', body: 'Something in your pantry needs using up.', tag: 'pantry-summary' })];
  }
  // Remember these so the app doesn't show them again. Browsers require every push to show a
  // notification, so one that was already shown just replaces itself quietly (same tag).
  const fresh = keys.length ? await markNotified(keys).catch(() => true) : true;
  await showNotifications(self.registration, notifications, { renotify: fresh });
}

self.addEventListener('push', (event) => event.waitUntil(handlePush(event)));

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = event.notification.data?.url || '#/alerts';
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      const client = windows.find((c) => c.url.startsWith(scope()));
      if (client) {
        await client.focus().catch(() => {});
        client.postMessage({ type: 'navigate', url });
      } else {
        await self.clients.openWindow(new URL(url, scope()).href);
      }
    })(),
  );
});

function base64UrlToBytes(value) {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(value.length / 4) * 4, '=');
  return Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
}

// The browser replaced our push subscription: send the new one (and the schedule) to the server.
async function resubscribe(event) {
  const push = (await kvGet('settings', {})).push;
  if (!push?.connected || !push.url) return;
  const headers = { 'Content-Type': 'application/json' };
  if (push.token) headers.Authorization = `Bearer ${push.token}`;
  let subscription = event.newSubscription;
  if (!subscription) {
    let key = event.oldSubscription?.options?.applicationServerKey;
    if (!key) {
      const res = await fetch(`${push.url}/api/vapid-public-key`, { headers });
      key = base64UrlToBytes((await res.json()).publicKey);
    }
    subscription = await self.registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: key });
  }
  const [schedule, notified] = await Promise.all([kvGet('schedule', []), kvGet('notified', [])]);
  const shown = new Set(notified);
  await fetch(`${push.url}/api/schedule`, {
    method: 'PUT',
    headers,
    body: JSON.stringify({
      subscription: subscription.toJSON(),
      entries: schedule.filter((e) => !shown.has(e.key)).slice(0, 500),
      oldEndpoint: event.oldSubscription?.endpoint,
    }),
  });
}

self.addEventListener('pushsubscriptionchange', (event) => event.waitUntil(resubscribe(event).catch(() => {})));
